        buc[i]++;
    }
    for(int i=1;i<=n;i++){
        if(buc[i]){
            if(!lcm){
                lcm=i;
            }
            lcm*=i/__gcd(lcm,i);
            ret=ret*C[num][i*buc[i]]%mod;
            int tmp=i*buc[i];
