int n,m,b,w,dp[N][N],C[N*N][N*N];
signed main(){
    cin>>n>>m>>b>>w;
    for(int i=0;i<N*N;i++){
        C[i][0]=1;
        for(int j=1;j<=i;j++){
            C[i][j]=(C[i-1][j]+C[i-1][j-1])%mod;
        }
    }
    for(int i=1;i<=n;i++){
        for(int j=1;j<=m;j++){//第一个i*j的棋盘 恰好每行每列都是有黑色的 且恰好放了b个棋子
            if(i*j>=b){
                dp[i][j]=C[i*j][b];
                for(int k=1;k<=i;k++){
                    for(int l=1;l<=j;l++){
                        if(k==i&&l==j){
                            continue;
                        }
                        dp[i][j]=(dp[i][j]-dp[k][l]*C[i][k]%mod*C[j][l])%mod;
                    }
                }
            }
        }
    }
    int ans=0;
    for(int i=1;i<=n;i++){
        for(int j=1;j<=m;j++){
            ans=(ans+dp[i][j]*C[n][i]%mod*C[m][j]%mod*C[(n-i)*(m-j)][w])%mod;        
        }
    }
    cout<<(ans%mod+mod)%mod;
}

