const int N=4e2+5,mod=998244353;
int n,m,a[N][N],mem[N][N],C[N][N];
int calc(int x,int y){
    int ret=0;
    for(int i=0;i<=y;i++){
        ret=(ret+C[x+y-i][y-i])%mod;
    }
    return ret;    
}
int dfs(int l,int r){
    if(l>r){
        return 1;
    }
    int &ret=mem[l][r];
    if(ret!=-1){
        return ret;
    }
    if((r-l+1)%2){
        return 0;
    }
    if(l+1==r){
        return a[l][r];
    }
    ret=0;
    for(int i=l+1;i<=r;i++){
        if(a[l][i]){//队列被分成了(i+1,r)与(l+1,i-1)两部分 其中第二部分必须在先前
            int len1=(r-(i+1))+1,len2=(i-1-(l+1))+1;
            if(len1%2==0&&len2%2==0){
                len1/=2,len2/=2;
                ret=(ret+dfs(i+1,r)*dfs(l+1,i-1)%mod*calc(len2,len1))%mod;   
            }
        }
    }
    return ret;
}
