    for(int u,v;m--;){
        cin>>u>>v,a[u][v]=a[v][u]=1;
    }
    for(int i=0;i<=n;i++){
        C[i][0]=1;
        for(int j=1;j<=i;j++){
            C[i][j]=(C[i-1][j]+C[i-1][j-1])%mod;
        }
    }
